var p = tree.root.get_node("Main/HUD_Right/VBoxContainer/RedeploymentScrollContainer/RedeploymentOuter/RedeploymentPanel")
var rows = p.get_node("UnitRows")
var head: String = p.get_node("HeaderLabel").text
return [head.contains("Kaptin's Hat"), head.contains("ORKS INFANTRY"), head.contains("(3 left)"), rows.get_child_count() == 2, rows.get_node_or_null("Row_U_BATTLEWAGON_A") == null, rows.get_node_or_null("Row_U_WARBOSS_A") == null, rows.get_node("Row_U_FLASH_GITZ_A/Name").text.contains("Warboss"), p.get_node("DoneButton").text.contains("Player 2 next")]

AIPlayer.enabled = false
AIPlayer.ai_players = {1: false, 2: false}
return true
